while True:
    resp = client.messages.create(model=MODEL, max_tokens=2048,
                                  tools=TOOLS, messages=history)
    history.append({"role": "assistant", "content": resp.content})
    if resp.stop_reason == "end_turn":
        return resp                      # finished
    if resp.stop_reason == "tool_use":
        history.append({"role": "user", "content": run_tools(resp)})
    elif resp.stop_reason == "pause_turn":
        continue                         # server tool paused: send it back
    else:  # max_tokens, refusal, context window: not a finished answer
        raise IncompleteReply(resp.stop_reason)

