verified = set()  # session ids with a verified customer

async def require_verification(inp, tool_use_id, ctx):
    if inp["session_id"] in verified:
        return {}
    return {"hookSpecificOutput": {
        "hookEventName": "PreToolUse",
        "permissionDecision": "deny",
        "permissionDecisionReason":
            "Verify the customer with verify_customer first."}}

async def normalize(inp, tool_use_id, ctx):
    data = parse(inp["tool_response"])
    data["date"] = to_iso(data["date"])  # 03/04/2026 to 2026-04-03
    data["status"] = STATUS_MAP.get(data["status"], "unknown")
    return {"hookSpecificOutput": {
        "hookEventName": "PostToolUse",
        "updatedToolOutput": data}}

hooks = {"PostToolUse": [HookMatcher(matcher="^mcp__orders__",
                                      hooks=[normalize])]}

async def refund_cap(inp, tool_use_id, ctx):
    if inp["tool_input"].get("amount", 0) <= 500:
        return {}
    return {"hookSpecificOutput": {
        "hookEventName": "PreToolUse",
        "permissionDecision": "deny",
        "permissionDecisionReason":
            "Refunds over 500 need a human. Call escalate_to_human."}}
